use axum::{
    body::Body,
    extract::MatchedPath,
    routing::{any, get},
    Router,
};
use http::{Request, StatusCode};
use tower::ServiceExt;

#[tokio::test]
async fn doesnt_panic_if_router_called_from_wildcard_route() {
    let app = Router::new().route(
        "/*path",
        any(|req: Request<Body>| {
            Router::new()
                .nest("/", Router::new().route("/foo", get(|| async {})))
                .oneshot(req)
        }),
    );

    let res = app
        .oneshot(
            Request::builder()
                .uri("/foo")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::OK);
}

async fn handler(path: Option<MatchedPath>, req: Request<Body>) {
    assert!(path.is_none());
    assert!(req.extensions().get::<MatchedPath>().is_none());
}

#[tokio::test]
async fn cant_extract_in_fallback() {
    let app = Router::new().fallback(handler);

    let res = app
        .oneshot(
            Request::builder()
                .uri("/foo/bar")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::OK);
}

